# Regenerating replaces the previous result.
#
# Every object a generation run creates is tagged with a generation id and
# the world matrix it was created with. When a later run produces a map that
# overlaps an earlier generation's map, that earlier generation is removed --
# but only the objects still sitting exactly where they were generated. Moving
# a result out of the way (or just nudging it) keeps it. Adjacent tiles
# (Extend mode) don't overlap, so they are never touched.

import functools
import re
import uuid
from contextlib import contextmanager

import bpy  # type: ignore
from mathutils import Vector  # type: ignore

GEN_ID = "tp3d_gen_id"
GEN_MATRIX = "tp3d_gen_matrix"

# Share of the smaller map's footprint two maps must overlap to count as
# "the same map regenerated" rather than neighbours.
_OVERLAP_SHARE = 0.5
_MATRIX_TOL = 1e-4
_SUFFIX = re.compile(r"^(.*)\.\d{3}$")


def _is_map(obj):
    return obj.type == 'MESH' and (obj.get("Object type") == "MAP" or obj.get("objType") == "MAP")


def _flat_matrix(obj):
    return [v for row in obj.matrix_world for v in row]


def tag_generated(obj, gen_id):
    """Mark *obj* as part of generation *gen_id*, at its current transform."""
    obj[GEN_ID] = gen_id
    obj[GEN_MATRIX] = _flat_matrix(obj)


def is_unmoved(obj):
    stored = obj.get(GEN_MATRIX)
    if stored is None or len(stored) != 16:
        return False
    return all(abs(a - b) <= _MATRIX_TOL for a, b in zip(stored, _flat_matrix(obj)))


def _xy_bounds(obj):
    corners = [obj.matrix_world @ Vector(c) for c in obj.bound_box]
    xs = [c.x for c in corners]
    ys = [c.y for c in corners]
    return min(xs), min(ys), max(xs), max(ys)


def _overlaps(a, b):
    ax0, ay0, ax1, ay1 = _xy_bounds(a)
    bx0, by0, bx1, by1 = _xy_bounds(b)
    w = min(ax1, bx1) - max(ax0, bx0)
    h = min(ay1, by1) - max(ay0, by0)
    if w <= 0 or h <= 0:
        return False
    smaller = min((ax1 - ax0) * (ay1 - ay0), (bx1 - bx0) * (by1 - by0))
    return smaller > 0 and (w * h) / smaller > _OVERLAP_SHARE


def _remove(obj):
    data = obj.data
    bpy.data.objects.remove(obj, do_unlink=True)
    if data is None or data.users:
        return
    if isinstance(data, bpy.types.Mesh):
        bpy.data.meshes.remove(data)
    elif isinstance(data, bpy.types.Curve):
        bpy.data.curves.remove(data)


def _strip_suffixes(objs):
    """Give new objects back their plain names ("Rectangle.001" -> "Rectangle")
    once the replaced originals are gone."""
    for obj in objs:
        m = _SUFFIX.match(obj.name)
        if m and m.group(1) not in bpy.data.objects:
            obj.name = m.group(1)


def replace_previous(new_objs):
    """Tag *new_objs* as one generation and remove the earlier, unmoved
    generations whose map they overlap. Returns the number of objects removed."""
    gen_id = uuid.uuid4().hex
    for obj in new_objs:
        tag_generated(obj, gen_id)

    new_maps = [o for o in new_objs if _is_map(o)]
    if not new_maps:
        return 0
    new_set = set(new_objs)

    groups = {}
    for obj in bpy.data.objects:
        gid = obj.get(GEN_ID)
        if gid and gid != gen_id and obj not in new_set:
            groups.setdefault(gid, []).append(obj)

    victims = []
    for members in groups.values():
        old_maps = [o for o in members if _is_map(o) and is_unmoved(o)]
        if any(_overlaps(old, new) for old in old_maps for new in new_maps):
            victims.extend(o for o in members if is_unmoved(o))

    for obj in victims:
        _remove(obj)
    if victims:
        _strip_suffixes([o for o in new_objs if o.name in bpy.data.objects])
    return len(victims)


def replaces_previous_generation(execute):
    """Decorator for an operator's execute(): see replacing_previous_generation()."""
    @functools.wraps(execute)
    def wrapper(self, context):
        with replacing_previous_generation():
            return execute(self, context)
    return wrapper


@contextmanager
def replacing_previous_generation():
    """Wrap a generation run: objects it creates replace the previous result.

    Nothing is replaced if the run raises.
    """
    before = {(o.as_pointer(), o.name) for o in bpy.data.objects}
    yield
    scene_objs = bpy.context.scene.objects
    new_objs = [o for o in bpy.data.objects
                if (o.as_pointer(), o.name) not in before and o.name in scene_objs]
    removed = replace_previous(new_objs)
    if removed:
        print(f"[TP3D] Replaced previous generation ({removed} object(s)) — move a result away to keep it.")
